// Reading a sample
// ---------------------------------------------------------------------------

TEST(TestFlydslSdpaBwdLaunchContractGoldens, SplitPrepV1SampleStillReadsAsItsContract)
{
    const SavedLaunchInputs inputs
        = serialization::readGoldenSample(SPLIT_PREP_V1_GOLDEN, prepSamplePayload());
    ASSERT_EQ(inputs.dispatchSymbol, "hipkernel.flydsl_sdpa_bwd_split.prep.dispatch.v1");

    const auto launch = readFlydslSdpaBwdPrepLaunchInputs(inputs);
    sample::expectSampleProblem(launch.problem);
    sample::expectSampleUidsAndScalars(launch.uids, launch.scalars);
    EXPECT_EQ(launch.headDim, 128);
    EXPECT_EQ(launch.grid, "qblocks_by_heads_by_seqs");
}

