// Writes one payload per contract as a C++ array, for a new sample to be checked in beside the
// ones already here. Excluded from every suite: it asserts nothing and only prints.
TEST(TestFlydslSdpaBwdLaunchContractGoldens, DISABLED_PrintLaunchContractSamples)
{
    serialization::printGoldenSample("SPLIT_PREP_V1_GOLDEN",
                                     serialization::encodeIngestorPlan(prepSamplePayload()));
    serialization::printGoldenSample("SPLIT_DKDV_V1_GOLDEN",
                                     serialization::encodeIngestorPlan(dkdvSamplePayload()));
    serialization::printGoldenSample("SPLIT_DQ_V1_GOLDEN",
                                     serialization::encodeIngestorPlan(dqSamplePayload()));
    serialization::printGoldenSample("SPLIT_DQ_REDUCE_V1_GOLDEN",
                                     serialization::encodeIngestorPlan(dqReduceSamplePayload()));
    serialization::printGoldenSample("SPLIT_DKDV_U2_V1_GOLDEN",
                                     serialization::encodeIngestorPlan(dkdvU2SamplePayload()));
    serialization::printGoldenSample("SPLIT_DQ_U2_V1_GOLDEN",
                                     serialization::encodeIngestorPlan(dqU2SamplePayload()));
    serialization::printGoldenSample("MERGED_V1_GOLDEN",
                                     serialization::encodeIngestorPlan(mergedSamplePayload()));
    serialization::printGoldenSample(
        "MERGED_REDUCE_V1_GOLDEN", serialization::encodeIngestorPlan(mergedReduceSamplePayload()));
}

